 var played=p.Folders[2].Songs[43];Call(c,"LoadPlayer",played);Call(c,"StartPlayer");Wait(()=>v.Player.Caption.Text==played.Title);Check(v.DisplayedSong==edited&&v.TagEditor.Title.Text==edited.Title,"Bearbeiteter Titel bleibt unabhängig vom Player");
 foreach(string page in new[]{"Bibliothek","Coversuche","Coverbearbeitung","Covergestaltung","Cover zuweisen / exportieren","MP3Gain","fre:ac","FFmpeg","Video-Audio-Import","Tag-Editor"}){Call(c,"OpenStudioModule",page);var buttons=All(v).OfType<Button>().Where(b=>b.Visible&&(b.Text=="Titelliste"||b.Text=="Ordner")).ToArray();Check(buttons.Length==2,page+" Bibliotheksnavigation ohne doppelte Titel/Ordner-Buttons");buttons.Single(x=>x.Text=="Ordner").PerformClick();Wait(()=>v.Groups.Visible);Check(v.DisplayedSong==edited,page+" zuletzt bearbeiteter Titel bleibt gespeichert");Check(v.Groups.Parent is StudioScrollFrame&&((StudioScrollFrame)v.Groups.Parent).Content==v.Groups,page+" eigene Ordner-Scrollfläche");buttons.Single(b=>b.Text=="Titelliste").PerformClick();Wait(()=>v.Songs.Visible&&v.Songs.SelectedRows.Count>0);Check(v.Songs.SelectedRows.Cast<DataGridViewRow>().Any(r=>r.Tag==edited),page+" bearbeiteter Titel wieder markiert");Check(v.Songs.Rows.Cast<DataGridViewRow>().Single(r=>r.Tag==edited).Displayed,page+" bearbeiteter Titel sichtbar");Check(v.Songs.SortedColumn.Name=="Titel"&&v.Songs.SortOrder==SortOrder.Descending,page+" Sortierung erhalten");Console.WriteLine(page+" Scrollwert: "+v.Songs.FirstDisplayedScrollingRowIndex+"/"+v.Songs.HorizontalScrollingOffset+" erwartet "+top+"/"+horizontal);Check(v.Songs.FirstDisplayedScrollingRowIndex==top&&v.Songs.HorizontalScrollingOffset==horizontal,page+" Scrollposition erhalten");Wait(()=>v.TitleCover.Image!=null);Check(((Bitmap)v.TitleCover.Image).GetPixel(0,0).R==255,page+" passendes Cover bleibt zugeordnet");Call(c,"PopulateLibrary");Check(v.Songs.FirstDisplayedScrollingRowIndex==top,page+" Aktualisierung nach Dateispeichern erhält Position");}
 foreach(var size in new[]{new Size(1000,680),new Size(1700,1000)}){v.ClientSize=size;Call(c,"OpenStudioModule","FFmpeg");Application.DoEvents();var table=(Control)Field(v,"studioLibrary");Check(!table.Bounds.IntersectsWith(v.ModuleHost.Bounds),"Werkzeug und Liste überlappen nicht "+size);var frame=(StudioScrollFrame)v.Songs.Parent;frame.RefreshRange();Check(v.Songs.ClientSize.Height>v.Songs.ColumnHeadersHeight+v.Songs.RowTemplate.Height,"Mindestens eine vollständige Titelzeile bleibt sichtbar "+size);Check(frame.Vertical.Maximum>0&&frame.Horizontal.Maximum>0,"Beide eigenen Scrollrichtungen vorhanden "+size);int target=Math.Min(frame.Vertical.Maximum,30);frame.Vertical.Value=target;Console.WriteLine("Scrollgriff: Zeile="+v.Songs.FirstDisplayedScrollingRowIndex+" Ziel="+target+" Griff="+frame.Vertical.Value+" Grid="+v.Songs.ClientSize+" Rahmen="+frame.Size);Check(v.Songs.FirstDisplayedScrollingRowIndex==target,"Eigener vertikaler Griff bewegt echte Zeilen");frame.Horizontal.Value=Math.Min(frame.Horizontal.Maximum,100);Check(v.Songs.HorizontalScrollingOffset==frame.Horizontal.Value,"Eigener horizontaler Griff bewegt echte Spalten");Check(v.Songs.ScrollBars==ScrollBars.None,"Native Grid-Scrollleisten ausgeschaltet");}
